PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS organizations(id TEXT PRIMARY KEY,name TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT,name TEXT,role TEXT NOT NULL DEFAULT 'owner',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS members(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,user_id TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'member',UNIQUE(organization_id,user_id));
CREATE TABLE IF NOT EXISTS agents(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,name TEXT NOT NULL,role TEXT,department TEXT,icon TEXT,color TEXT,prompt TEXT,personality TEXT,responsibilities TEXT,goals TEXT,rules TEXT,forbidden_actions TEXT,communication_style TEXT,decision_policy TEXT,escalation_policy TEXT,provider_id TEXT,model TEXT,temperature REAL DEFAULT .4,max_tokens INTEGER DEFAULT 3000,memory_enabled INTEGER DEFAULT 1,permissions TEXT,schedule TEXT,enabled INTEGER DEFAULT 1,status TEXT DEFAULT 'offline',manager_id TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS agent_versions(id TEXT PRIMARY KEY,agent_id TEXT NOT NULL,version INTEGER NOT NULL,prompt TEXT,config TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS providers(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,name TEXT NOT NULL,base_url TEXT NOT NULL,model TEXT,api_key_enc TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS departments(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,name TEXT NOT NULL,icon TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS projects(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,name TEXT NOT NULL,description TEXT,status TEXT DEFAULT 'active',progress INTEGER DEFAULT 0,owner_agent_id TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS tasks(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,title TEXT NOT NULL,description TEXT,priority TEXT DEFAULT 'normal',status TEXT DEFAULT 'pending',agent_id TEXT,created_by TEXT,department TEXT,project_id TEXT,deadline TEXT,result TEXT,error TEXT,attempts INTEGER DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,started_at TEXT,finished_at TEXT);
CREATE TABLE IF NOT EXISTS task_dependencies(id TEXT PRIMARY KEY,task_id TEXT NOT NULL,depends_on_task_id TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS runs(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,task_id TEXT,agent_id TEXT,status TEXT,model TEXT,usage TEXT,trace TEXT,error TEXT,started_at TEXT,finished_at TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS messages(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,agent_id TEXT,task_id TEXT,role TEXT,content TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS memories(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,agent_id TEXT,type TEXT DEFAULT 'long_term',content TEXT NOT NULL,importance INTEGER DEFAULT 1,pinned INTEGER DEFAULT 0,source TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS knowledge_documents(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,name TEXT NOT NULL,mime_type TEXT,size INTEGER DEFAULT 0,r2_key TEXT,status TEXT DEFAULT 'ready',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS knowledge_chunks(id TEXT PRIMARY KEY,document_id TEXT NOT NULL,content TEXT NOT NULL,chunk_index INTEGER,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS tools(id TEXT PRIMARY KEY,name TEXT UNIQUE NOT NULL,description TEXT,enabled INTEGER DEFAULT 1,requires_approval INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS agent_tools(id TEXT PRIMARY KEY,agent_id TEXT NOT NULL,tool_id TEXT NOT NULL,enabled INTEGER DEFAULT 1,requires_approval INTEGER DEFAULT 0,UNIQUE(agent_id,tool_id));
CREATE TABLE IF NOT EXISTS workflows(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,name TEXT NOT NULL,description TEXT,nodes TEXT,edges TEXT,status TEXT DEFAULT 'draft',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS workflow_runs(id TEXT PRIMARY KEY,workflow_id TEXT NOT NULL,status TEXT,context TEXT,trace TEXT,error TEXT,started_at TEXT,finished_at TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS schedules(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,agent_id TEXT,workflow_id TEXT,cron TEXT,event_type TEXT,enabled INTEGER DEFAULT 1,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notifications(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,user_id TEXT,title TEXT,body TEXT,type TEXT,read INTEGER DEFAULT 0,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS approvals(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,agent_id TEXT,task_id TEXT,action TEXT,resource TEXT,payload TEXT,status TEXT DEFAULT 'pending',decided_by TEXT,decision_note TEXT,created_at TEXT NOT NULL,decided_at TEXT);
CREATE TABLE IF NOT EXISTS logs(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,agent_id TEXT,task_id TEXT,run_id TEXT,action TEXT,message TEXT,error TEXT,meta TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_logs(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,user_id TEXT,agent_id TEXT,action TEXT,resource TEXT,result TEXT,approval_id TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS usage(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,agent_id TEXT,provider TEXT,model TEXT,requests INTEGER DEFAULT 0,input_tokens INTEGER DEFAULT 0,output_tokens INTEGER DEFAULT 0,cost REAL DEFAULT 0,date TEXT NOT NULL,UNIQUE(organization_id,agent_id,provider,model,date));
CREATE TABLE IF NOT EXISTS settings(organization_id TEXT NOT NULL,key TEXT NOT NULL,value TEXT,PRIMARY KEY(organization_id,key));
CREATE INDEX IF NOT EXISTS idx_tasks_org_status ON tasks(organization_id,status);CREATE INDEX IF NOT EXISTS idx_logs_org_time ON logs(organization_id,created_at);CREATE INDEX IF NOT EXISTS idx_memory_agent ON memories(organization_id,agent_id);CREATE INDEX IF NOT EXISTS idx_runs_org_time ON runs(organization_id,created_at);
INSERT OR IGNORE INTO tools(id,name,description,enabled,requires_approval) VALUES ('tool-calculator','calculator','محاسبات امن داخلی',1,0),('tool-http','http_request','درخواست HTTP خروجی با کنترل دامنه',1,1),('tool-memory','memory','خواندن/نوشتن حافظه Agent',1,0),('tool-delegate','delegate','واگذاری Task به Agent دیگر',1,0),('tool-github','github','اتصال GitHub از طریق Secret',0,1);
